PRAGMA foreign_keys = ON;

-- YottaFlex AI Workforce Retention Analytics
-- SQLite schema; synthetic data only. IDs are generated by the application.

CREATE TABLE IF NOT EXISTS Role (
    role_id TEXT PRIMARY KEY,
    role_name TEXT NOT NULL UNIQUE,
    role_category TEXT NOT NULL,
    created_at TEXT NOT NULL,
    CHECK (length(trim(role_name)) > 0),
    CHECK (length(trim(role_category)) > 0)
);

CREATE TABLE IF NOT EXISTS Team (
    team_id TEXT PRIMARY KEY,
    team_name TEXT NOT NULL UNIQUE,
    department_name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    CHECK (length(trim(team_name)) > 0),
    CHECK (length(trim(department_name)) > 0)
);

CREATE TABLE IF NOT EXISTS CompensationBand (
    compensation_band_id TEXT PRIMARY KEY,
    band_name TEXT NOT NULL UNIQUE,
    level_order INTEGER NOT NULL UNIQUE,
    currency_code TEXT NOT NULL DEFAULT 'INR',
    minimum_amount REAL,
    maximum_amount REAL,
    CHECK (level_order > 0),
    CHECK (length(currency_code) = 3),
    CHECK (minimum_amount IS NULL OR minimum_amount >= 0),
    CHECK (maximum_amount IS NULL OR maximum_amount >= 0),
    CHECK (minimum_amount IS NULL OR maximum_amount IS NULL OR minimum_amount <= maximum_amount)
);

CREATE TABLE IF NOT EXISTS Employee (
    employee_id TEXT PRIMARY KEY,
    employment_start_date TEXT NOT NULL,
    initial_role_id TEXT NOT NULL,
    initial_team_id TEXT NOT NULL,
    initial_compensation_band_id TEXT,
    employment_status TEXT NOT NULL DEFAULT 'Active',
    created_at TEXT NOT NULL,
    FOREIGN KEY (initial_role_id) REFERENCES Role(role_id),
    FOREIGN KEY (initial_team_id) REFERENCES Team(team_id),
    FOREIGN KEY (initial_compensation_band_id) REFERENCES CompensationBand(compensation_band_id),
    CHECK (employment_status IN ('Active', 'OnLeave', 'Terminated')),
    CHECK (date(employment_start_date) IS NOT NULL),
    CHECK (date(created_at) IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS EmployeeAssignmentHistory (
    assignment_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    role_id TEXT NOT NULL,
    team_id TEXT NOT NULL,
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    change_reason TEXT NOT NULL,
    recorded_at TEXT NOT NULL,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    FOREIGN KEY (role_id) REFERENCES Role(role_id),
    FOREIGN KEY (team_id) REFERENCES Team(team_id),
    CHECK (date(effective_from) IS NOT NULL),
    CHECK (effective_to IS NULL OR date(effective_to) IS NOT NULL),
    CHECK (effective_to IS NULL OR date(effective_to) >= date(effective_from)),
    CHECK (change_reason IN ('InitialAssignment', 'Transfer', 'Promotion', 'Reorganization', 'Correction'))
);
CREATE INDEX IF NOT EXISTS idx_assignment_employee_dates ON EmployeeAssignmentHistory(employee_id, effective_from, effective_to);

CREATE TABLE IF NOT EXISTS EmployeeCompensationHistory (
    compensation_history_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    compensation_band_id TEXT NOT NULL,
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    change_reason TEXT NOT NULL,
    recorded_at TEXT NOT NULL,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    FOREIGN KEY (compensation_band_id) REFERENCES CompensationBand(compensation_band_id),
    CHECK (date(effective_from) IS NOT NULL),
    CHECK (effective_to IS NULL OR date(effective_to) IS NOT NULL),
    CHECK (effective_to IS NULL OR date(effective_to) >= date(effective_from)),
    CHECK (change_reason IN ('InitialAssignment', 'BandChange', 'Promotion', 'Correction'))
);
CREATE INDEX IF NOT EXISTS idx_comp_history_employee_dates ON EmployeeCompensationHistory(employee_id, effective_from, effective_to);

CREATE TABLE IF NOT EXISTS TenureSnapshot (
    snapshot_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    snapshot_date TEXT NOT NULL,
    tenure_days INTEGER NOT NULL,
    employment_status TEXT NOT NULL,
    observation_period TEXT NOT NULL,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    UNIQUE (employee_id, snapshot_date),
    CHECK (date(snapshot_date) IS NOT NULL),
    CHECK (tenure_days >= 0),
    CHECK (employment_status IN ('Active', 'OnLeave', 'Terminated')),
    CHECK (length(trim(observation_period)) > 0)
);

CREATE TABLE IF NOT EXISTS EngagementSurvey (
    survey_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    survey_date TEXT NOT NULL,
    engagement_score REAL,
    response_status TEXT NOT NULL,
    survey_version TEXT NOT NULL,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    UNIQUE (employee_id, survey_date, survey_version),
    CHECK (date(survey_date) IS NOT NULL),
    CHECK (engagement_score IS NULL OR (engagement_score >= 1 AND engagement_score <= 5)),
    CHECK (response_status IN ('Completed', 'Missing', 'Partial', 'NotInvited')),
    CHECK ((response_status = 'Completed' AND engagement_score IS NOT NULL) OR response_status <> 'Completed')
);

CREATE TABLE IF NOT EXISTS WorkloadSnapshot (
    workload_snapshot_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    period_start TEXT NOT NULL,
    period_end TEXT NOT NULL,
    workload_hours_per_week REAL,
    workload_pressure_score REAL,
    workload_category TEXT NOT NULL,
    measurement_source TEXT NOT NULL,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    UNIQUE (employee_id, period_start, period_end),
    CHECK (date(period_start) IS NOT NULL AND date(period_end) IS NOT NULL),
    CHECK (date(period_end) >= date(period_start)),
    CHECK (workload_hours_per_week IS NULL OR workload_hours_per_week >= 0),
    CHECK (workload_pressure_score IS NULL OR (workload_pressure_score >= 0 AND workload_pressure_score <= 100)),
    CHECK (workload_category IN ('Low', 'Normal', 'High', 'Unknown')),
    CHECK (measurement_source IN ('SyntheticSchedule', 'SyntheticSurvey', 'SyntheticManagerEstimate'))
);

CREATE TABLE IF NOT EXISTS PromotionHistory (
    promotion_event_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    event_date TEXT NOT NULL,
    previous_role_id TEXT,
    new_role_id TEXT NOT NULL,
    progression_type TEXT NOT NULL,
    notes TEXT,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    FOREIGN KEY (previous_role_id) REFERENCES Role(role_id),
    FOREIGN KEY (new_role_id) REFERENCES Role(role_id),
    CHECK (date(event_date) IS NOT NULL),
    CHECK (progression_type IN ('Promotion', 'LateralMove', 'CareerLevelChange', 'RoleExpansion'))
);

CREATE TABLE IF NOT EXISTS AttritionOutcome (
    outcome_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    scoring_date TEXT NOT NULL,
    horizon_days INTEGER NOT NULL DEFAULT 90,
    outcome_window_end TEXT NOT NULL,
    outcome_status TEXT NOT NULL,
    termination_date TEXT,
    termination_type TEXT,
    label_voluntary_attrition INTEGER,
    censoring_reason TEXT,
    label_version TEXT NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    UNIQUE (employee_id, scoring_date, horizon_days, label_version),
    CHECK (date(scoring_date) IS NOT NULL),
    CHECK (date(outcome_window_end) IS NOT NULL),
    CHECK (horizon_days > 0),
    CHECK (date(outcome_window_end) >= date(scoring_date)),
    CHECK (termination_date IS NULL OR date(termination_date) IS NOT NULL),
    CHECK (outcome_status IN ('ObservedAttrition', 'ObservedNoAttrition', 'Censored', 'Pending')),
    CHECK (termination_type IS NULL OR termination_type IN ('Voluntary', 'Involuntary', 'Retirement', 'Other')),
    CHECK (label_voluntary_attrition IS NULL OR label_voluntary_attrition IN (0, 1)),
    CHECK ((outcome_status = 'Censored' AND label_voluntary_attrition IS NULL) OR outcome_status <> 'Censored'),
    CHECK ((outcome_status = 'ObservedAttrition' AND termination_date IS NOT NULL AND termination_type = 'Voluntary' AND label_voluntary_attrition = 1) OR outcome_status <> 'ObservedAttrition'),
    CHECK ((outcome_status = 'ObservedNoAttrition' AND label_voluntary_attrition = 0) OR outcome_status <> 'ObservedNoAttrition')
);

CREATE TABLE IF NOT EXISTS ScoringRun (
    scoring_run_id TEXT PRIMARY KEY,
    scoring_date TEXT NOT NULL,
    ruleset_version TEXT NOT NULL,
    score_method TEXT NOT NULL,
    seed INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (ruleset_version) REFERENCES RulesetVersion(ruleset_version),
    CHECK (date(scoring_date) IS NOT NULL),
    CHECK (score_method IN ('RuleBasedBaseline', 'MachineLearning'))
);

CREATE TABLE IF NOT EXISTS RulesetVersion (
    ruleset_version TEXT PRIMARY KEY,
    description TEXT NOT NULL,
    effective_from TEXT NOT NULL,
    created_at TEXT NOT NULL,
    CHECK (date(effective_from) IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS RetentionRecommendation (
    recommendation_id TEXT PRIMARY KEY,
    scoring_run_id TEXT NOT NULL,
    employee_id TEXT NOT NULL,
    priority_score REAL NOT NULL,
    priority_category TEXT NOT NULL,
    evidence_start_date TEXT NOT NULL,
    evidence_end_date TEXT NOT NULL,
    contributing_factors_json TEXT NOT NULL,
    data_quality_warnings_json TEXT NOT NULL,
    conversation_topics_json TEXT NOT NULL,
    human_review_status TEXT NOT NULL DEFAULT 'PendingReview',
    created_at TEXT NOT NULL,
    FOREIGN KEY (scoring_run_id) REFERENCES ScoringRun(scoring_run_id),
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    UNIQUE (scoring_run_id, employee_id),
    CHECK (priority_score >= 0 AND priority_score <= 100),
    CHECK (priority_category IN ('Low', 'Medium', 'High')),
    CHECK (date(evidence_start_date) IS NOT NULL AND date(evidence_end_date) IS NOT NULL),
    CHECK (date(evidence_end_date) >= date(evidence_start_date)),
    CHECK (human_review_status IN ('PendingReview', 'Accepted', 'Deferred', 'Rejected', 'Completed'))
);

CREATE TABLE IF NOT EXISTS RecommendationReview (
    review_id TEXT PRIMARY KEY,
    recommendation_id TEXT NOT NULL,
    reviewer_reference TEXT NOT NULL,
    decision TEXT NOT NULL,
    reason TEXT NOT NULL,
    reviewed_at TEXT NOT NULL,
    FOREIGN KEY (recommendation_id) REFERENCES RetentionRecommendation(recommendation_id),
    CHECK (decision IN ('Accepted', 'Deferred', 'Rejected')),
    CHECK (length(trim(reason)) > 0),
    CHECK (date(reviewed_at) IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS Intervention (
    intervention_id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    recommendation_id TEXT,
    intervention_type TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'Proposed',
    proposed_date TEXT NOT NULL,
    scheduled_date TEXT,
    completed_date TEXT,
    cancelled_date TEXT,
    follow_up_due_date TEXT,
    simulated_outcome TEXT,
    outcome_is_simulated INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    FOREIGN KEY (employee_id) REFERENCES Employee(employee_id),
    FOREIGN KEY (recommendation_id) REFERENCES RetentionRecommendation(recommendation_id),
    CHECK (intervention_type IN ('WorkloadConversation', 'CareerDevelopment', 'EngagementCheckIn', 'WorkplaceSupport', 'OtherSupport')),
    CHECK (status IN ('Proposed', 'Scheduled', 'Completed', 'Deferred', 'Cancelled')),
    CHECK (outcome_is_simulated IN (0, 1)),
    CHECK (date(proposed_date) IS NOT NULL),
    CHECK (scheduled_date IS NULL OR date(scheduled_date) IS NOT NULL),
    CHECK (completed_date IS NULL OR date(completed_date) IS NOT NULL),
    CHECK (cancelled_date IS NULL OR date(cancelled_date) IS NOT NULL),
    CHECK (follow_up_due_date IS NULL OR date(follow_up_due_date) IS NOT NULL),
    CHECK (simulated_outcome IS NULL OR simulated_outcome IN ('Improved', 'Unchanged', 'Worsened', 'InsufficientData')),
    CHECK (status <> 'Completed' OR completed_date IS NOT NULL),
    CHECK (status <> 'Cancelled' OR cancelled_date IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS InterventionEvent (
    intervention_event_id TEXT PRIMARY KEY,
    intervention_id TEXT NOT NULL,
    event_date TEXT NOT NULL,
    previous_status TEXT,
    new_status TEXT NOT NULL,
    event_reason TEXT NOT NULL,
    recorded_by_reference TEXT NOT NULL,
    FOREIGN KEY (intervention_id) REFERENCES Intervention(intervention_id),
    CHECK (date(event_date) IS NOT NULL),
    CHECK (previous_status IS NULL OR previous_status IN ('Proposed', 'Scheduled', 'Completed', 'Deferred', 'Cancelled')),
    CHECK (new_status IN ('Proposed', 'Scheduled', 'Completed', 'Deferred', 'Cancelled')),
    CHECK (length(trim(event_reason)) > 0)
);

CREATE TABLE IF NOT EXISTS AuditLog (
    audit_event_id TEXT PRIMARY KEY,
    event_timestamp TEXT NOT NULL,
    actor_reference TEXT NOT NULL,
    entity_name TEXT NOT NULL,
    entity_id TEXT NOT NULL,
    action TEXT NOT NULL,
    change_summary TEXT NOT NULL,
    reason TEXT,
    CHECK (action IN ('CREATE', 'UPDATE', 'STATUS_CHANGE', 'REVIEW', 'EXPORT', 'VALIDATION')),
    CHECK (length(trim(entity_name)) > 0),
    CHECK (length(trim(entity_id)) > 0),
    CHECK (length(trim(change_summary)) > 0)
);

CREATE INDEX IF NOT EXISTS idx_survey_employee_date ON EngagementSurvey(employee_id, survey_date);
CREATE INDEX IF NOT EXISTS idx_workload_employee_period ON WorkloadSnapshot(employee_id, period_start, period_end);
CREATE INDEX IF NOT EXISTS idx_tenure_employee_date ON TenureSnapshot(employee_id, snapshot_date);
CREATE INDEX IF NOT EXISTS idx_outcome_employee_scoring_date ON AttritionOutcome(employee_id, scoring_date);
CREATE INDEX IF NOT EXISTS idx_recommendation_category ON RetentionRecommendation(priority_category, human_review_status);
CREATE INDEX IF NOT EXISTS idx_intervention_status ON Intervention(status, proposed_date);
CREATE INDEX IF NOT EXISTS idx_intervention_event_date ON InterventionEvent(intervention_id, event_date);

-- Enforce that a completed survey has a score; missing surveys remain NULL rather than score 1.
-- More complex temporal overlap and cross-table lifecycle rules are checked by Python validators.
